import json

with open("/workspace/DEMOS.json") as f:
    demos = json.load(f)

# Categorize by input/output length relationship
categories = {}
for demo in demos:
    tid = demo["task_id"]
    inputs = demo["input_examples"]
    outputs = demo["output_examples"]
    first_inp = inputs[0] if inputs else []
    first_out = outputs[0] if outputs else []

    if len(first_inp) == len(first_out):
        cat = "same_length"
    elif len(first_out) > len(first_inp):
        cat = "expanding"
    else:
        cat = "shrinking"

    if tid not in categories:
        categories[tid] = {"cat": cat, "demo": demo}

for tid, info in sorted(categories.items()):
    d = info["demo"]
    inp = d["input_examples"][0]
    out = d["output_examples"][0]
    print(f"{tid:6s} {info['cat']:15s} len_in={len(inp)} len_out={len(out)}  inp={inp}  out={out}")

