import json

with open("/workspace/DEMOS.json") as f:
    demos = json.load(f)

# Analyze remaining tasks
for tid in ['c114', 'c118', 'c122', 'c126', 'c184', 'c201', 'c218', 'c165', 'c164', 'c241', 'c245']:
    demo = [d for d in demos if d['task_id'] == tid][0]
    print(f"\n=== {tid} ===")
    for i, (inp, out) in enumerate(zip(demo['input_examples'][:3], demo['output_examples'][:3])):
        print(f"  {i}: In={inp}  Out={out}")

    # Try to identify patterns
    demo = [d for d in demos if d['task_id'] == tid][0]
    inp, out = demo['input_examples'][0], demo['output_examples'][0]

    # Check various common patterns
    if len(out) == len(inp):
        print(f"  len_check: same_length")
        if out == inp[::-1]:
            print(f"  reverse_match: YES")

    if len(out) < len(inp):
        print(f"  shrinking: in_len={len(inp)} out_len={len(out)}")
        # Check if it's slice [1:-1], [1:], [:-1], etc.
        if out == inp[1:]:
            print(f"  slice[1:]: YES")
        if out == inp[:-1]:
            print(f"  slice[:-1]: YES")
        if out == inp[1:-1]:
            print(f"  slice[1:-1]: YES")

    if len(out) == 1:
        print(f"  length 1 output")
        vals = set(demo['output_examples'])
        if len(vals) == 1:
            print(f"  constant output: {vals}")

    # Check for min/max
    demo = [d for d in demos if d['task_id'] == tid][0]
    all_out = demo['output_examples']
    if all(len(o) == 1 for o in all_out):
        # What's the relation?
        for i2, (inp2, out2) in enumerate(zip(demo['input_examples'][:5], demo['output_examples'][:5])):
            print(f"    inp={inp2}, out={out2}, max={max(inp2) if inp2 else 'N/A'}, min={min(inp2) if inp2 else 'N/A'}, sum={sum(inp2) if inp2 else 0}")

