# --- Count-based selection ---
def prim_keep_mode(xs):
    """Keep only the mode (most frequent) element, one copy."""
    if not xs:
        return []
    c = Counter(xs)
    m = max(c.values())
    for x in xs:
        if c[x] == m:
            return [x]
    return []

def prim_keep_top_k_modes(xs, k=2):
    """Keep top k modes."""
    if not xs:
        return []
    c = Counter(xs)
    m = max(c.values())
    result = []
    seen = set()
    for x in xs:
        if c[x] == m and x not in seen:
            result.append(x)
            seen.add(x)
            if len(result) >= k:
                break
    return result

