# ---------------------------------------------------------------------------

def compose(fns):
    """Compose a list of functions: f_n o f_{n-1} o ... o f_1."""
    def fn(xs):
        result = list(xs)
        for f in fns:
            result = f(result)
        return result
    return fn

def compose_desc(fns):
    """Create description of composed functions."""
    return " o ".join(desc for desc, _ in fns)


