def generate_source_program(fn, desc, examples):
    """Generate a readable Python source program from a candidate."""
    # Try to infer what the function does and generate clean code
    if not examples:
        return None

    # Test on first example to understand behavior
    inp0, out0 = examples[0]

    # Check if it's a constant function
    all_same = True
    for inp, out in examples:
        try:
            if fn(list(inp)) != out:
                all_same = False
                break
        except:
            all_same = False
    if all_same and len(examples) > 0:
        return f"def program(xs):\n    return {out0!r}\n"

    # Try to generate descriptive code based on the description
    if "const" in desc.lower():
        val = fn(list(inp0))
        return f"def program(xs):\n    return {val!r}\n"

    if "count_elements" in desc:
        return """def program(xs):
    if not xs:
        return []
    m = max(xs)
    return [xs.count(i) for i in range(1, m + 1)]
"""

    if "filter_even" in desc and "reverse" in desc:
        return """def program(xs):
    return list(reversed([x for x in xs if x % 2 == 0]))
"""

    if "filter_even" in desc:
        return """def program(xs):
    return [x for x in xs if x % 2 == 0]
"""

    if "filter_odd" in desc:
        return """def program(xs):
    return [x for x in xs if x % 2 != 0]
"""

    if "filter_nonzero" in desc:
        return """def program(xs):
    return [x for x in xs if x != 0]
"""

    if "reverse" in desc and "slice" in desc:
        return """def program(xs):
    return list(reversed(xs))
"""

    if "reverse" in desc:
        return """def program(xs):
    return list(reversed(xs))
"""

    if "sort" in desc:
        rev = "True" if "desc" in desc else "False"
        return f"""def program(xs):
    return sorted(xs, reverse={rev})
"""

    if "rotate_left" in desc or "rotL" in desc:
        parts = desc.split("_")
        k = int(parts[-1]) if parts[-1].isdigit() else 1
        return f"""def program(xs):
    if not xs:
        return []
    k = {k} % len(xs)
    return list(xs[k:]) + list(xs[:k])
"""

    if "rotate_right" in desc or "rotR" in desc:
        parts = desc.split("_")
        k = int(parts[-1]) if parts[-1].isdigit() else 1
        return f"""def program(xs):
    if not xs:
        return []
    k = {k} % len(xs)
    return list(xs[-k:]) + list(xs[:-k])
"""

    if "slice" in desc and "1n1" in desc:
        return """def program(xs):
    return list(xs[1:-1])
"""

    if "slice" in desc and "1n" in desc:
        return """def program(xs):
    return list(xs[1:])
"""

    if "odd_idx" in desc:
        return """def program(xs):
    return [xs[i] for i in range(1, len(xs), 2)]
"""

    if "even_idx" in desc:
        return """def program(xs):
    return [xs[i] for i in range(0, len(xs), 2)]
"""

    if "dedup" in desc and "consec" in desc:
        return """def program(xs):
    if not xs:
        return []
    out = [xs[0]]
    for x in xs[1:]:
        if x != out[-1]:
            out.append(x)
    return out
"""

    if "dedup" in desc:
        return """def program(xs):
    seen = set()
    out = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out
"""

    if "first" in desc:
        return """def program(xs):
    return [xs[0]] if xs else []
"""

    if "last" in desc:
        return """def program(xs):
    return [xs[-1]] if xs else []
"""

    if "max" in desc:
