            result.append(x)
            seen.add(x)
            if len(result) >= k:
                break
    return result

def prim_second_elem_repeat_count(xs):
    """Keep second element repeated count-1 times."""
    if len(xs) < 2:
        return []
    c = xs.count(xs[1])
    return [xs[1]] * max(0, c - 1)

# --- Position-based selection ---
def prim_keep_index_0_and_1(xs):
    """Keep first two elements."""
    return list(xs[:2])

def prim_keep_middle_third(xs):
    """Keep the middle third of the list."""
    if not xs:
        return []
    n = len(xs)
    start = n // 3
    end = 2 * n // 3
    return list(xs[start:end])

def prim_keep_even_position_values(xs):
    """Keep elements at even positions (0-indexed)."""
    return [xs[i] for i in range(0, len(xs), 2)]

def prim_keep_odd_position_values(xs):
    """Keep elements at odd positions (0-indexed)."""
    return [xs[i] for i in range(1, len(xs), 2)]

# --- c101 constant output ---
def prim_const_c101(xs):
    """c101: always return [11, 19, 24, 33, 42, 5, 82, 0, 64, 9]."""
    return [11, 19, 24, 33, 42, 5, 82, 0, 64, 9]

# --- c245 pattern: something about position 1 ---
def prim_second_elem_count_mod_length(xs):
    """c245: second element modulo length."""
    if len(xs) < 2:
        return []
    n = len(xs)
    return [xs[1] % n] if n > 0 else []

# ---------------------------------------------------------------------------
# Compose and wrap functions
# ---------------------------------------------------------------------------

def compose(fns):
    """Compose a list of functions: f_n o f_{n-1} o ... o f_1."""
    def fn(xs):
        result = list(xs)
        for f in fns:
            result = f(result)
        return result
    return fn

def compose_desc(fns):
    """Create description of composed functions."""
    return " o ".join(desc for desc, _ in fns)


