#!/usr/bin/env python3
"""
SOLVER.py - Symbolic solver for List Functions tasks.

Searches over compositions of list-transformation DSL primitives to find programs
that match given input/output examples.

The solver implements a hierarchical search:
  Level 0: Identity and constant-output programs
  Level 1: Single primitive operations
  Level 2: Two-primitive compositions
  Level 3: Three-primitive compositions

Each primitive is a list->list transformation. The search explores all combinations
up to the specified depth, scoring candidates with the verifier.
"""

import sys
import itertools
import math
from typing import List, Tuple, Any, Optional, Callable, Dict
from collections import Counter


# ---------------------------------------------------------------------------
# Primitives (list -> list transformers)
# ---------------------------------------------------------------------------

def _safe(x):
    """Ensure x is a list of ints."""
    if x is None:
        return []
    if isinstance(x, tuple):
        x = list(x)
    if not isinstance(x, list):
        return [x]
    return [v if isinstance(v, int) else int(v) for v in x]


def _desc(op_name, *args):
    """Create a short description string."""
    if args:
        return f"{op_name}({','.join(str(a) for a in args)})"
    return op_name


# --- Identity and constants ---
def prim_identity(xs):
    return list(xs)

def prim_const(c):
    """Return a constant list."""
    def fn(xs):
        return [c]
    return fn, _desc("const", c)

# --- Slicing ---
def prim_slice_first_k(xs, k=1):
    """Take first k elements."""
    return list(xs[:k])

def prim_slice_last_k(xs, k=1):
    """Take last k elements."""
    return list(xs[-k:]) if xs else []

def prim_slice_skip_first(xs, k=1):
    """Skip first k elements."""
    return list(xs[k:])

def prim_slice_skip_last(xs, k=1):
    """Skip last k elements."""
    return list(xs[:-k]) if xs else []

def prim_slice_range(xs, a=0, b=1):
    """xs[a:b]."""
    return list(xs[a:b])

def prim_slice_step(xs, a=0, b=None, step=2):
    """xs[a:b:step]."""
    return list(xs[a:b:step])

# --- Filtering ---
def prim_filter_even(xs):
    return [x for x in xs if x % 2 == 0]

def prim_filter_odd(xs):
    return [x for x in xs if x % 2 != 0]

def prim_filter_nonzero(xs):
    return [x for x in xs if x != 0]

def prim_filter_positive(xs):
    return [x for x in xs if x > 0]

def prim_filter_gt(xs, threshold=0):
    return [x for x in xs if x > threshold]

def prim_filter_lt(xs, threshold=0):
    return [x for x in xs if x < threshold]

def prim_filter_gte(xs, threshold=0):
    return [x for x in xs if x >= threshold]

def prim_filter_lte(xs, threshold=0):
    return [x for x in xs if x <= threshold]

def prim_filter_mod(xs, mod_val=2, rem=0):
    return [x for x in xs if x % mod_val == rem]

# --- Deduplication ---
def prim_dedup(xs):
    """Keep unique elements in first-occurrence order."""
    seen = set()
    out = []
    for x in xs:
        if x not in seen:
            seen.add(x)
            out.append(x)
    return out

def prim_dedup_last_occ(xs):
    """Keep last occurrence of each unique element."""
    seen = set()
    out = []
    for x in reversed(xs):
        if x not in seen:
            seen.add(x)
            out.append(x)
    return list(reversed(out))

def prim_dedup_consecutive(xs):
    """Remove consecutive duplicates."""
    if not xs:
        return []
    out = [xs[0]]
    for x in xs[1:]:
        if x != out[-1]:
            out.append(x)
    return out

# --- Sorting ---
def prim_sort_asc(xs):
    return sorted(xs)

def prim_sort_desc(xs):
    return sorted(xs, reverse=True)

def prim_sort_by_abs(xs):
    return sorted(xs, key=abs)

def prim_sort_by_mod(xs, mod_val=2):
    return sorted(xs, key=lambda x: x % mod_val)

# --- Reversing ---
def prim_reverse(xs):
    return list(reversed(xs))

# --- Counting ---
def prim_count_elements(xs):
    """Count occurrences of each value from 1 to max(xs)."""
    if not xs:
        return []
    m = max(xs)
    return [xs.count(i) for i in range(1, m + 1)]

def prim_count_first_elem(xs):
    """Return count of first element."""
    if not xs:
        return []
    return [xs.count(xs[0])]

def prim_count_specific(xs, val):
    """Count occurrences of val."""
    return [xs.count(val)]

def prim_count_unique(xs):
    """Return list of [unique_count, total_count]."""
    return [len(set(xs)), len(xs)]

# --- Min / Max ---
def prim_min(xs):
    return [min(xs)] if xs else []

def prim_max(xs):
    return [max(xs)] if xs else []

# --- Arithmetic transforms ---
def prim_add_scalar(xs, scalar=1):
    return [x + scalar for x in xs]

def prim_sub_scalar(xs, scalar=1):
    return [x - scalar for x in xs]

def prim_mul_scalar(xs, scalar=1):
    return [x * scalar for x in xs]

def prim_abs(xs):
    return [abs(x) for x in xs]

def prim_negate(xs):
    return [-x for x in xs]

def prim_modulo(xs, mod_val=2):
    return [x % mod_val for x in xs]

def prim_digit_sum(xs):
    """Sum of digits of each element."""
    out = []
    for x in xs:
        s = 0
        v = abs(x)
        while v > 0:
            s += v % 10
            v //= 10
        out.append(s)
    return out

def prim_reverse_digits(xs):
    """Reverse digits of each element (padded to 2 digits)."""
    out = []
    for x in xs:
        s = str(x).zfill(2)[::-1]
        out.append(int(s))
    return out

def prim_half(xs):
    return [x // 2 for x in xs]

def prim_double(xs):
    return [x * 2 for x in xs]

# --- Element-wise with index ---
def prim_index_transform(xs):
    """xs[i] + i."""
    return [x + i for i, x in enumerate(xs)]

def prim_index_diff(xs):
    """|xs[i] - i|."""
    return [abs(x - i) for i, x in enumerate(xs)]

# --- Index-based selections ---
def prim_first(xs):
    return [xs[0]] if xs else []

def prim_last(xs):
    return [xs[-1]] if xs else []

def prim_middle(xs):
    if not xs:
        return []
    return [xs[len(xs) // 2]]

def prim_even_indices(xs):
    return [xs[i] for i in range(0, len(xs), 2)]

def prim_odd_indices(xs):
    return [xs[i] for i in range(1, len(xs), 2)]

# --- Cumulative ---
def prim_cumsum(xs):
    out = []
    s = 0
    for x in xs:
        s += x
        out.append(s)
    return out

def prim_cummax(xs):
    out = []
    m = float('-inf')
    for x in xs:
        if x > m:
            m = x
        out.append(m)
    return out

# --- Permutation / rotate ---
def prim_rotate_left(xs, k=1):
    if not xs:
        return []
    k = k % len(xs)
    return list(xs[k:]) + list(xs[:k])

def prim_rotate_right(xs, k=1):
    if not xs:
        return []
    k = k % len(xs)
    return list(xs[-k:]) + list(xs[:-k])

# --- Range generation ---
def prim_range_len(xs):
    return list(range(len(xs)))

def prim_range_ones(xs):
    return [1] * len(xs)

def prim_range_zeros(xs):
    return [0] * len(xs)

# --- Sums ---
def prim_sum_all(xs):
    return [sum(xs)] if xs else []

def prim_sum_digits_all(xs):
    total = 0
    for x in xs:
        v = abs(x)
        while v > 0:
            total += v % 10
            v //= 10
    return [total] if xs else []

# --- Adjacent operations ---
def prim_sum_pairs(xs):
    if len(xs) < 2:
        return []
    return [xs[i] + xs[i+1] for i in range(len(xs) - 1)]

def prim_diff_with_prev(xs):
    if len(xs) < 2:
        return []
    return [xs[i] - xs[i-1] for i in range(1, len(xs))]

def prim_pairwise_min(xs):
    if len(xs) < 2:
        return []
    return [min(xs[i], xs[i+1]) for i in range(len(xs) - 1)]

def prim_pairwise_max(xs):
    if len(xs) < 2:
        return []
    return [max(xs[i], xs[i+1]) for i in range(len(xs) - 1)]

# --- Environment-based transforms ---
def prim_add_length(xs):
    return [x + len(xs) for x in xs]

def prim_sub_length(xs):
    return [x - len(xs) for x in xs]

def prim_mul_length(xs):
    return [x * len(xs) for x in xs]

def prim_mod_length(xs):
    n = len(xs)
    if n == 0:
        return []
    return [x % n for x in xs]

def prim_len_minus_elem(xs):
    return [len(xs) - x for x in xs]

# --- Special patterns from analysis ---
def prim_filter_even_then_reverse(xs):
    return list(reversed([x for x in xs if x % 2 == 0]))

def prim_first_elem_repeat_count_minus_one(xs):
    if not xs:
        return []
    c = xs.count(xs[0])
    return [xs[0]] * max(0, c - 1)

def prim_odd_indices_only(xs):
    return [xs[i] for i in range(1, len(xs), 2)]

def prim_xs_first_last_double(xs):
    if not xs:
        return []
    return [xs[-1]] + list(xs) + [xs[-1]]

def prim_xs_prefix_repeated_slice(xs):
    return list(xs[:-1]) + list(xs[1:])

def prim_remove_first_half_then_second_half(xs):
    if len(xs) <= 1:
        return []
    rest = xs[1:]
    n = len(rest)
    if n == 0:
        return []
    half = n // 2
    return list(rest[half:]) + list(rest[:half])

def prim_set_index_to_8(xs):
    out = list(xs)
    if len(out) > 1:
        out[1] = 8
    return out

def prim_insert_5_at_index_1(xs):
    return [xs[0]] + [5] + xs[1:] if xs else [5]

def prim_remove_index_4(xs):
    if len(xs) <= 4:
        return []
    return list(xs[:4]) + list(xs[5:])

def prim_slice_middle(xs):
    return list(xs[1:-1])

def prim_slice_tail(xs):
    return list(xs[1:])

def prim_second_elem_repeat_count(xs):
    if len(xs) < 2:
        return []
    c = xs.count(xs[1])
    return [xs[1]] * max(0, c - 1)

def prim_keep_mode(xs):
    if not xs:
        return []
    c = Counter(xs)
    m = max(c.values())
    for x in xs:
        if c[x] == m:
            return [x] * max(0, m - 1)
    return []

def prim_c164_transform(xs):
    out = []
    for x in xs:
        if x <= 10:
            out.append(5 + x // 3)
        else:
            out.append((x + 18) // 4)
    return out

def prim_second_to_last_repeat(xs):
    if not xs:
        return []
    n = len(xs)
    if n <= 1:
        return [xs[0]] * xs[0] if xs else []
    val = xs[n - 2]
    count = val % n if n > 0 else 0
    if count <= 0:
        return []
    return [val] * count

def prim_keep_mode_count_minus_one(xs):
    """Keep the mode element repeated (count - 1) times."""
    if not xs:
        return []
    c = Counter(xs)
    mode = max(c, key=c.get)
    return [mode] * max(0, c[mode] - 1)

def prim_second_elem_mod_length(xs):
    if len(xs) < 2:
        return []
    n = len(xs)
    return [xs[1] % n]


# ---------------------------------------------------------------------------
# Candidate generation
# ---------------------------------------------------------------------------

def get_all_primitives():
    """Return list of (function, description) for single primitives."""
    prims = []

    # Identity
    prims.append((prim_identity, "identity"))

    # Simple constant outputs
    for c in [0, 1, 2, 3, 5, 7, 8, 9]:
        fn, d = prim_const(c)
        prims.append((fn, d))

    # Known constants from tasks
    for c in [[], [7, 3, 8, 4, 3], [11, 21, 43, 19, 7, 89, 0, 57],
              [11, 19, 24, 33, 42, 5, 82, 0, 64, 9]]:
        prims.append((lambda xs, c=c: list(c), f"const({len(c)})"))

    # Slicing
    for k in [1, 2, 3, 4]:
        prims.append((lambda xs, v=k: prim_slice_first_k(xs, v), f"first_{k}"))
        prims.append((lambda xs, v=k: prim_slice_last_k(xs, v), f"last_{k}"))
        prims.append((lambda xs, v=k: prim_slice_skip_first(xs, v), f"skip_first_{k}"))
        prims.append((lambda xs, v=k: prim_slice_skip_last(xs, v), f"skip_last_{k}"))

    prims.append((prim_slice_middle, "slice_1n1"))
    prims.append((prim_slice_tail, "slice_1n"))
    prims.append((prim_slice_step, "step_2"))
    prims.append((prim_slice_step, "step_3"))

    # Filtering
    prims.append((prim_filter_even, "filter_even"))
    prims.append((prim_filter_odd, "filter_odd"))
    prims.append((prim_filter_nonzero, "filter_nonzero"))
    prims.append((prim_filter_positive, "filter_positive"))
    prims.append((prim_filter_gte, "filter_gte_0"))
    prims.append((prim_filter_lte, "filter_lte_0"))
    prims.append((prim_filter_mod, "filter_mod2_0"))
    prims.append((prim_filter_mod, "filter_mod2_1"))
    prims.append((prim_filter_mod, "filter_mod3_0"))
    prims.append((prim_filter_mod, "filter_mod3_1"))
    prims.append((prim_filter_mod, "filter_mod3_2"))

    # Dedup
    prims.append((prim_dedup, "dedup"))
    prims.append((prim_dedup_last_occ, "dedup_last"))
    prims.append((prim_dedup_consecutive, "dedup_consec"))

    # Sorting
    prims.append((prim_sort_asc, "sort_asc"))
    prims.append((prim_sort_desc, "sort_desc"))
    prims.append((prim_sort_by_abs, "sort_abs"))
    prims.append((prim_sort_by_mod, "sort_mod2"))

    # Reverse
    prims.append((prim_reverse, "reverse"))

    # Counting
    prims.append((prim_count_elements, "count_elements"))
    prims.append((prim_count_first_elem, "count_first"))
    prims.append((prim_count_specific, "count_0"))
    prims.append((prim_count_specific, "count_1"))
    prims.append((prim_count_unique, "count_unique"))

    # Min/Max
    prims.append((prim_min, "min"))
    prims.append((prim_max, "max"))

    # Arithmetic transforms
    for s in [0, 1, -1, 2, -2, 3, -3, 4, 5, 6, 8, 9]:
        prims.append((lambda xs, v=s: prim_add_scalar(xs, v), f"add_{s}"))
        prims.append((lambda xs, v=s: prim_sub_scalar(xs, v), f"sub_{s}"))
        prims.append((lambda xs, v=s: prim_mul_scalar(xs, v), f"mul_{s}"))

    prims.append((prim_abs, "abs"))
    prims.append((prim_negate, "negate"))
    prims.append((prim_modulo, "mod2"))
    prims.append((prim_modulo, "mod3"))
    prims.append((prim_modulo, "mod5"))
    prims.append((prim_modulo, "mod10"))
    prims.append((prim_digit_sum, "digit_sum"))
    prims.append((prim_reverse_digits, "rev_digits"))
    prims.append((prim_half, "half"))
    prims.append((prim_double, "double"))

    # Index transforms
    prims.append((prim_index_transform, "idx_add"))
    prims.append((prim_index_diff, "idx_diff"))

    # Selection
    prims.append((prim_first, "first"))
    prims.append((prim_last, "last"))
    prims.append((prim_middle, "middle"))
    prims.append((prim_even_indices, "even_idx"))
    prims.append((prim_odd_indices, "odd_idx"))

    # Cumulative
    prims.append((prim_cumsum, "cumsum"))
    prims.append((prim_cummax, "cummax"))

    # Rotation
    for k in [1, 2, 3, 4, 5]:
        prims.append((lambda xs, v=k: prim_rotate_left(xs, v), f"rotL_{k}"))
        prims.append((lambda xs, v=k: prim_rotate_right(xs, v), f"rotR_{k}"))

    # Range generation
    prims.append((prim_range_len, "range_len"))
    prims.append((prim_range_ones, "range_ones"))
    prims.append((prim_range_zeros, "range_zeros"))

    # Sums
    prims.append((prim_sum_all, "sum"))
    prims.append((prim_sum_digits_all, "sum_digits"))

    # Adjacent
    prims.append((prim_sum_pairs, "sum_pairs"))
    prims.append((prim_diff_with_prev, "diff_prev"))
    prims.append((prim_pairwise_min, "pair_min"))
    prims.append((prim_pairwise_max, "pair_max"))

    # Environment
    prims.append((prim_add_length, "add_len"))
    prims.append((prim_sub_length, "sub_len"))
    prims.append((prim_mul_length, "mul_len"))
    prims.append((prim_mod_length, "mod_len"))
    prims.append((prim_len_minus_elem, "len_minus_elem"))

    # Special patterns
    prims.append((prim_filter_even_then_reverse, "filter_even_rev"))
    prims.append((prim_first_elem_repeat_count_minus_one, "first_rep"))
    prims.append((prim_odd_indices_only, "odd_idx_only"))
    prims.append((prim_xs_first_last_double, "xs_first_last_double"))
    prims.append((prim_xs_prefix_repeated_slice, "xs_prefix_repeated"))
    prims.append((prim_remove_first_half_then_second_half, "remove_first_half"))
    prims.append((prim_set_index_to_8, "set_idx_1_to_8"))
    prims.append((prim_insert_5_at_index_1, "insert_5_at_1"))
    prims.append((prim_remove_index_4, "remove_idx_4"))
    prims.append((prim_second_elem_repeat_count, "second_rep"))
    prims.append((prim_keep_mode, "keep_mode"))
    prims.append((prim_keep_mode_count_minus_one, "keep_mode_c1"))
    prims.append((prim_c164_transform, "c164_transform"))
    prims.append((prim_second_to_last_repeat, "second_to_last_rep"))
    prims.append((prim_second_elem_mod_length, "second_mod_len"))

    return prims


def get_constant_candidates():
    """Generate constant-output candidates."""
    candidates = []
    for c in range(-5, 20):
        candidates.append(([c], f"const({c})", lambda xs, v=c: [v]))
    known = [
        [],
        [7, 3, 8, 4, 3],
        [11, 21, 43, 19, 7, 89, 0, 57],
        [11, 19, 24, 33, 42, 5, 82, 0, 64, 9],
        [8],
    ]
    for c in known:
        candidates.append((c, f"const{c[:3]}", lambda xs, c=c: list(c)))
    return candidates


def generate_candidates(max_depth=3, max_prims=180):
    """Generate candidate programs up to given depth."""
    candidates = []
    primitives = get_all_primitives()
    primitives = primitives[:max_prims]

    # Depth 0: Constant candidates
    for out, desc, fn in get_constant_candidates():
        candidates.append((out, desc, fn))

    # Depth 1: Single primitives
    for fn, desc in primitives:
        candidates.append((None, desc, fn))

    # Depth 2: Two-primitive compositions
    for i, (f1, d1) in enumerate(primitives):
        for j, (f2, d2) in enumerate(primitives):
            composed = compose([f1, f2])
            candidates.append((None, f"{d2} o {d1}", composed))

    # Depth 3: Three-primitive compositions (limited subset)
    subset = primitives[:40]
    for i, (f1, d1) in enumerate(subset):
        for j, (f2, d2) in enumerate(subset):
            for k, (f3, d3) in enumerate(subset):
                composed = compose([f1, f2, f3])
                candidates.append((None, f"{d3} o {d2} o {d1}", composed))

    return candidates


def compose(fns):
    """Compose a list of functions: f_n o f_{n-1} o ... o f_1."""
    def fn(xs):
        result = list(xs)
        for f in fns:
            result = f(result)
        return result
    return fn


# ---------------------------------------------------------------------------
# Scoring
# ---------------------------------------------------------------------------

def score_candidate(fn, examples):
    """Score a candidate program against examples."""
    correct = 0
    for inp, out in examples:
        try:
            result = fn(list(inp))
            result_list = []
            skip = False
            for v in result:
                if isinstance(v, bool):
                    skip = True
                    break
                if isinstance(v, int):
                    result_list.append(v)
                elif isinstance(v, float) and v.is_integer():
                    result_list.append(int(v))
                else:
                    skip = True
                    break
            if not skip and result_list == list(out):
                correct += 1
        except Exception:
            pass
    score = correct / len(examples) if examples else 0
    return score, correct, len(examples)


