        "first_rep": "def program(xs):\n    if not xs:\n        return []\n    c = xs.count(xs[0])\n    return [xs[0]] * max(0, c - 1)\n",
        "second_rep": "def program(xs):\n    if len(xs) < 2:\n        return []\n    c = xs.count(xs[1])\n    return [xs[1]] * max(0, c - 1)\n",
