    c = Counter(xs)
    mode = max(c, key=c.get)
    return [mode] * max(0, c[mode] - 1)

def prim_c164_transform(xs):
    out = []
    for x in xs:
        if x <= 10:
            out.append(5 + x // 3)
        else:
            out.append((x + 18) // 4)
    return out

def prim_second_to_last_repeat(xs):
    if not xs:
        return []
    n = len(xs)
    if n <= 1:
        return [xs[0]] * xs[0] if xs else []
    val = xs[n - 2]
    count = val % n if n > 0 else 0
    if count <= 0:
        return []
    return [val] * count

def prim_second_elem_mod_length(xs):
    if len(xs) < 2:
        return []
    return [xs[1] % len(xs)]

def prim_first_then_last(xs):
    if not xs:
        return []
    if len(xs) == 1:
        return [xs[0]]
    return [xs[0]] + [xs[-1]]

def prim_drop_first_n_by_first_elem(xs):
    """c130: xs[1:xs[0]+1]"""
    if not xs:
        return []
    n = xs[0]
    return list(xs[1:n+1])

def prim_count_even(xs):
    """c241: count even numbers."""
    return [sum(1 for x in xs if x % 2 == 0)]

def prim_product_all(xs):
    """c109: product of all elements."""
    if not xs:
        return [1]
    p = 1
    for x in xs:
        p *= x
    return [p]

def prim_min_multiple_length(xs):
    """c203: multiples of min, length len."""
    if not xs:
        return []
    m = min(xs)
    n = len(xs)
    return [m * i for i in range(1, n + 1)]

def prim_prepend_suffix(xs, prefix=None, suffix=None):
    """c068/c097: prepend/append constants."""
    if prefix is None:
        prefix = []
    if suffix is None:
        suffix = []
    return list(prefix) + list(xs) + list(suffix)

def prim_append_const(xs, values):
    """Append a constant list."""
    return list(xs) + list(values)

def prim_prepend_const(xs, values):
    """Prepend a constant list."""
    return list(values) + list(xs)

def prim_filter_zero_then_reverse(xs):
    """c250: filter zeros, then reverse."""
    return list(reversed([x for x in xs if x != 0]))


